import {writeFileSync,mkdirSync} from 'node:fs';
import {BoxGeometry,MeshStandardMaterial,MeshBasicMaterial,BufferGeometry,BufferAttribute,Matrix4} from 'three';
import {staticGlb} from '@wildshard/sharddev/bake/glb';
import {bakeRawColourPixels} from '@wildshard/sharddev/bake/rawTexture';
const dir='test/fixtures/sdk-built/assets';mkdirSync(dir,{recursive:true});
const put=(name,rows)=>{writeFileSync(`${dir}/${name}.glb`,staticGlb(rows));for(const row of rows){row.geometry.dispose();row.material.dispose();}};
for(const [file,name,native,width,height,depth,colour] of [
 ['hero','hero',true,1,2,3,0x345678],['hull','source',true,1,2,3,0x345678],
 ['specimen','specimen',false,1,1,1,0xffffff],['bound-specimen','bound-specimen',false,1,1,1,0xffffff],['retry-specimen','retry-specimen',false,1,1,1,0xffffff]])
 put(file,[{name,geometry:new BoxGeometry(width,height,depth),material:new MeshStandardMaterial({color:colour}),...(native?{nativeAttributes:true}:{})}]);
const triangle=()=>new BufferGeometry().setAttribute('position',new BufferAttribute(new Float32Array([0,0,0,1,0,0,0,1,0]),3));
const scene=triangle();scene.setAttribute('normal',new BufferAttribute(new Float32Array([0,0,1,0,0,1,0,0,1]),3));scene.setAttribute('uv',new BufferAttribute(new Float32Array(6),2));put('scene',[{geometry:scene,material:new MeshStandardMaterial(),nativeAttributes:true}]);
for(const part of ['draw','other'])for(const posed of [false,true]) {
 const shape=triangle();shape.setAttribute('normal',new BufferAttribute(new Float32Array([0,0,2,0,0,2,0,0,2]),3));
 put(`whole-${part}-${posed?'posed':'plain'}`,[{geometry:shape,material:new MeshBasicMaterial(),nativeAttributes:true,transform:posed?new Matrix4().makeTranslation(3,2,1):new Matrix4(),extras:{wholePartition:{id:part,vertices:{runs:[0,3]},triangles:{runs:[0,1]},vertexCount:3,indexCount:0,index:'none'}}}]);
}
const pixels=Uint8ClampedArray.from({length:8*4*4},(_,index)=>(index*31+17)%256);
for(const colourSpace of ['srgb','linear'])writeFileSync(`${dir}/raw-${colourSpace}.ktx2`,bakeRawColourPixels({width:8,height:4,pixels},{colourSpace}));
for(let i=0;i<8;i++) {
 const part=`phase-${i}`,shape=triangle();shape.setAttribute('normal',new BufferAttribute(new Float32Array([0,0,2,0,0,2,0,0,2]),3));
 put(`whole-${part}-plain`,[{geometry:shape,material:new MeshBasicMaterial(),nativeAttributes:true,transform:new Matrix4(),extras:{wholePartition:{id:part,vertices:{runs:[0,3]},triangles:{runs:[0,1]},vertexCount:3,indexCount:0,index:'none'}}}]);
}

exportRecipes.ci21-product-specimen.mjs:
import {writeFileSync,readFileSync} from 'node:fs';
import {createHash} from 'node:crypto';
import {BoxGeometry,MeshStandardMaterial} from 'three';
import {staticGlb} from '<checkouts>/sharddev/src/sharddev/bake/glb.ts';
import {bakeRawColourPixels} from '<checkouts>/sharddev/src/sharddev/bake/rawTexture.ts';
const dir='test/fixtures/sdk-built/assets',manifest=JSON.parse(readFileSync(dir+'/manifest.json','utf8'));
function put(name,bytes){writeFileSync(dir+'/'+name,bytes);manifest.files[name]={bytes:bytes.length,sha256:createHash('sha256').update(bytes).digest('hex'),sourceRepository:'project-wildshard/sharddev',sourceCommit:'da2a4ddb564db35b5c3bcba4ba1358de92ced1af'};}
for(const width of [2,8]){const geometry=new BoxGeometry(width,2,3),material=new MeshStandardMaterial();try{put(`product-crate-${width}.glb`,staticGlb([{name:'crate',geometry,material}]));}finally{geometry.dispose();material.dispose();}}
const pixels=Uint8ClampedArray.from({length:32},(_,index)=>(index*37+19)%256);
put('product-crate.ktx2',bakeRawColourPixels({width:4,height:2,pixels}));
put('product-crate-phone.ktx2',bakeRawColourPixels({width:4,height:2,pixels:Uint8ClampedArray.from(pixels,value=>255-value)}));
manifest.exportRecipes['ci21-product-specimen.mjs']=readFileSync('tmp/codex-tc48/export-assets.mjs','utf8').replaceAll('<checkouts>/','<checkouts>/');
writeFileSync(dir+'/manifest.json',JSON.stringify(manifest,null,2)+'\n');
